// 📚 ดึงความรู้ทุกสินค้าจากเว็บ iduckystore.com (ทีละหน้า 25 สินค้า) → รายการ {text, metadata} สำหรับฝังลง Pinecone
// ปลายทาง: GET /api/pricing/search?knowledge=1&offset=&limit=25 (แต่ละหน้า ~10-20 วิ)
const BASE = 'https://iduckystore.com/api/pricing/search?knowledge=1&limit=25&offset=';
const out = [];
let offset = 0;
for (let guard = 0; guard < 40 && offset !== null; guard++) {
  const page = await this.helpers.httpRequest({ method: 'GET', url: BASE + offset, json: true, timeout: 60000, headers: { 'User-Agent': 'n8n-website-knowledge-sync' } });
  for (const it of (page.items || [])) {
    out.push({ json: {
      text: `คำถาม: ${it.question}\n\nคำตอบ: ${it.answer}`,
      metadata: { id: it.id, question: it.question, product: it.product, productId: it.productId, type: it.type, url: it.url, source: 'website', syncedAt: new Date().toISOString() }
    } });
  }
  offset = (page.next === null || page.next === undefined) ? null : page.next;
}
if (!out.length) throw new Error('website knowledge: no items — ยกเลิกไม่ให้ล้าง namespace ทิ้ง');
return out;
